public:
    int slidingPuzzle(vector<vector<int>>& board) {
        string start = "";
        for (const auto& row : board) {
            for (int v : row) start += to_string(v);
        }
        string target = "123450";
        vector<vector<int>> moves = {
            {1, 3}, {0, 2, 4}, {1, 5},
            {0, 4}, {1, 3, 5}, {2, 4}
        };
        queue<pair<string, int>> q;
        unordered_set<string> visited;
        q.push({start, 0});
        visited.insert(start);
        while (!q.empty()) {
            auto [state, step] = q.front();
            q.pop();
            if (state == target) return step;
            int zero_idx = state.find('0');
            for (int nxt : moves[zero_idx]) {
                string next_state = state;
                swap(next_state[zero_idx], next_state[nxt]);
                if (!visited.count(next_state)) {
                    visited.insert(next_state);
                    q.push({next_state, step + 1});
                }
            }
        }
        return -1;
    }
};

class Solution {
    public int slidingPuzzle(int[][] board) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : board) {
            for (int v : row) sb.append(v);
        }
        String start = sb.toString();
        String target = "123450";
        int[][] moves = {
            {1, 3}, {0, 2, 4}, {1, 5},
            {0, 4}, {1, 3, 5}, {2, 4}
        };
        Queue<String> q = new ArrayDeque<>();
        Map<String, Integer> dist = new HashMap<>();
        q.add(start);
        dist.put(start, 0);
        while (!q.isEmpty()) {
            String state = q.poll();
            int step = dist.get(state);
            if (state.equals(target)) return step;
            int zeroIdx = state.indexOf('0');
            for (int nxt : moves[zeroIdx]) {
                char[] chars = state.toCharArray();
                char tmp = chars[zeroIdx];
                chars[zeroIdx] = chars[nxt];
                chars[nxt] = tmp;
                String nextState = new String(chars);
                if (!dist.containsKey(nextState)) {
                    dist.put(nextState, step + 1);
                    q.add(nextState);
                }
            }
        }
        return -1;
    }
}

var slidingPuzzle = function(board) {
    const start = board.flat().join("");
    const target = "123450";
    const moves = [
        [1, 3], [0, 2, 4], [1, 5],
        [0, 4], [1, 3, 5], [2, 4]
    ];
    const q = [[start, 0]];
    const visited = new Set([start]);
    while (q.length > 0) {
        const [state, step] = q.shift();
        if (state === target) return step;
        const zeroIdx = state.indexOf("0");
        for (const nxt of moves[zeroIdx]) {
            const arr = state.split("");
            const tmp = arr[zeroIdx];
            arr[zeroIdx] = arr[nxt];
            arr[nxt] = tmp;
            const nextState = arr.join("");
            if (!visited.has(nextState)) {
                visited.add(nextState);
                q.push([nextState, step + 1]);
            }
        }
    }
    return -1;
};
